insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0000-0000000000c1','00000000-0000-0000-0000-0000000000a2','00000000-0000-0000-0000-0000000000e2','Ross says he left at 10:30 PM; the gate log shows 11:20 PM.');
insert into cases(id,number,title,difficulty,category,intro,location,est_minutes,motives,methods) values('00000000-0000-0000-0002-c00000000000',2,'The Stolen Violin','easy','Theft','The 1742 Corelli violin vanished from the Marlowe Conservatory''s locked display case during Friday rehearsal. Three people had access to the hall.','Marlowe Conservatory, Hall B',15,array['Tuition debt','Revenge on the professor','Insurance fraud'],array['Smashed the case','Used a copied access card','Swapped it during rehearsal']);
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0002-a00000000000','00000000-0000-0000-0002-c00000000000','Prof. Adler',58,'Conservatory director','Owns the instrument collection.','The collection is underinsured.','Conducting rehearsal on stage.','"I never left the podium."');
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0002-a00000000001','00000000-0000-0000-0002-c00000000000','Mira Quill',21,'Student violinist','Scholarship student.','Owes the bursar a large balance.','Says she went home at 8 PM.','"I left before the hall emptied."');
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0002-a00000000002','00000000-0000-0000-0002-c00000000000','Gus Penn',47,'Caretaker','Twenty years on staff.','None known.','Mopping the east corridor.','"I never touched the case."');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0002-e00000000000','00000000-0000-0000-0002-c00000000000','Display case','Hall B','The glass is intact and the lock undamaged; it was opened with a valid card.','Rules out a break-in');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0002-e00000000001','00000000-0000-0000-0002-c00000000000','Access log','Security office','Mira Quill''s card opened Hall B at 9:10 PM. Gus''s card shows no entry after 7 PM.','Tests Mira''s alibi');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0002-e00000000002','00000000-0000-0000-0002-c00000000000','Rehearsal video','Stage camera','Adler is in frame conducting from 8:45 to 9:30 PM.','Clears Adler');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0002-e00000000003','00000000-0000-0000-0002-c00000000000','Pawn ticket','Mira''s locker','A ticket dated Saturday for a violin, under a false name.','Shows intent to sell');
insert into case_solutions values('00000000-0000-0000-0002-c00000000000','00000000-0000-0000-0002-a00000000001',0,1,'Mira said she left at 8 PM, but the access log puts her card in Hall B at 9:10. The case was opened with a card, not forced, and the video clears Adler for the whole window. Her tuition debt and the pawn ticket give the motive.',array['00000000-0000-0000-0002-e00000000001','00000000-0000-0000-0002-e00000000003']::uuid[]);
insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0002-c00000000000','00000000-0000-0000-0002-a00000000001','00000000-0000-0000-0002-e00000000001','Mira says she left at 8 PM; her card opened Hall B at 9:10 PM.');
insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0002-c00000000000','00000000-0000-0000-0002-a00000000000','00000000-0000-0000-0002-e00000000002','Adler''s statement holds: video shows him conducting during the theft.');
insert into cases(id,number,title,difficulty,category,intro,location,est_minutes,motives,methods) values('00000000-0000-0000-0003-c00000000000',3,'Poison at the Regatta','medium','Homicide','Commodore Lila Hart collapsed during the Harbor Club awards dinner and died within the hour. Nobody else fell ill.','Harbor Club ballroom',30,array['Jealous rivalry','Covering up embezzlement','Inheritance'],array['Poisoned buffet food','Poisoned trophy cup','Tampered medication']);
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0003-a00000000000','00000000-0000-0000-0003-c00000000000','Dr. Ben Okafor',50,'Club physician','Treated Lila for a heart condition.','None beyond his duty.','Seated at table two all evening.','"I tried to save her. I touched nothing."');
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0003-a00000000001','00000000-0000-0000-0003-c00000000000','Sofia Reyes',29,'Rival skipper','Lost the regatta to Lila.','Sent Lila an angry letter.','On stage accepting second place.','"I hated losing, not her."');
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0003-a00000000002','00000000-0000-0000-0003-c00000000000','Tom Wick',35,'Caterer','Plated the dinner.','His contract was not renewed.','In the kitchen.','"Every guest ate the same menu."');
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0003-a00000000003','00000000-0000-0000-0003-c00000000000','Greta Lund',46,'Club treasurer','Keeps the books and tends a greenhouse.','Lila called for an audit.','Says she was counting raffle tickets.','"I haven''t opened the club ledger in weeks."');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0003-e00000000000','00000000-0000-0000-0003-c00000000000','Trophy cup','Head table','Only Lila drank from it during the toast; residue tests positive for digitalis.','Identifies the poison and delivery');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0003-e00000000001','00000000-0000-0000-0003-c00000000000','Catering sheet','Kitchen','All guests ate the same menu and nobody else fell ill.','Rules out the food');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0003-e00000000002','00000000-0000-0000-0003-c00000000000','Club ledger','Treasurer''s office','Forty thousand missing; recent entries signed by Greta; an audit was set for Monday.','Reveals a motive');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0003-e00000000003','00000000-0000-0000-0003-c00000000000','Greenhouse receipt','Garden shed','Foxglove cuttings, a digitalis source, bought from Greta''s greenhouse a week ago.','Links the poison to a person');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0003-e00000000004','00000000-0000-0000-0003-c00000000000','Angry letter','Lila''s cabin','Sofia vows to beat her on the water, nothing more.','Red herring: rivalry, no threat of harm');
insert into case_solutions values('00000000-0000-0000-0003-c00000000000','00000000-0000-0000-0003-a00000000003',1,1,'Only Lila drank from the trophy cup, and it held digitalis. Greta''s greenhouse supplied the foxglove, and the ledger shows she had stolen forty thousand with an audit due Monday. Killing Lila stopped the audit.',array['00000000-0000-0000-0003-e00000000000','00000000-0000-0000-0003-e00000000002','00000000-0000-0000-0003-e00000000003']::uuid[]);
insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0003-c00000000000','00000000-0000-0000-0003-a00000000003','00000000-0000-0000-0003-e00000000002','Greta says she hasn''t opened the ledger in weeks; her signature is on recent entries.');
insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0003-c00000000000','00000000-0000-0000-0003-a00000000003','00000000-0000-0000-0003-e00000000003','Greta''s greenhouse is the source of the foxglove.');
insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0003-c00000000000','00000000-0000-0000-0003-a00000000002','00000000-0000-0000-0003-e00000000001','Wick''s statement holds: the food was safe for everyone.');
insert into cases(id,number,title,difficulty,category,intro,location,est_minutes,motives,methods) values('00000000-0000-0000-0004-c00000000000',4,'The Clockmaker''s Alibi','medium','Homicide','Clockmaker Ansel Roe was found dead in his shop. Every clock had stopped at 9:00 PM, yet something about the hour feels wrong.','Roe & Daughter Clockworks',30,array['Stolen patent','Unpaid wages','Family inheritance'],array['Struck, then staged the time on the clocks','Pushed down the stairs','Gassed in a locked room']);
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0004-a00000000000','00000000-0000-0000-0004-c00000000000','Cass Doyle',52,'Rival clockmaker','Lost a patent dispute to Roe.','Roe''s escapement design beat his.','At the Orpheum, show began 9:15 PM.','"I was watching a play when he died."');
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0004-a00000000001','00000000-0000-0000-0004-c00000000000','Wren Hale',24,'Apprentice','Paid late for months.','Owed three months'' wages.','Eating at the corner cafe.','"I left the shop at 6 PM."');
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0004-a00000000002','00000000-0000-0000-0004-c00000000000','Pip Roe',30,'Nephew','Heir to the shop.','Inherits the building.','Visiting a friend out of town.','"I wasn''t in town."');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0004-e00000000000','00000000-0000-0000-0004-c00000000000','Clock hands','Shop floor','All hands set to 9:00, with tobacco oil on the winding stems.','Shows the time was staged by a smoker');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0004-e00000000001','00000000-0000-0000-0004-c00000000000','Coroner''s note','Coroner','Body temperature puts death near 7:30 PM, long before 9:00.','Breaks the shop''s timeline');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0004-e00000000002','00000000-0000-0000-0004-c00000000000','Theater stub','Cass''s coat','Seat stub for the 9:15 show, bought at 5 PM that day.','Shows an alibi built in advance');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0004-e00000000003','00000000-0000-0000-0004-c00000000000','Patent drawings','Hidden drawer','Roe''s drawings with a torn corner that matches a scrap in Cass''s workshop.','Links Cass to the motive');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0004-e00000000004','00000000-0000-0000-0004-c00000000000','Cafe receipt','Wren''s pocket','Timed 7:05 PM at a cafe three blocks from the shop.','Clears Wren');
insert into case_solutions values('00000000-0000-0000-0004-c00000000000','00000000-0000-0000-0004-a00000000000',0,0,'The clocks said 9:00 but Ansel died near 7:30, so someone set them to build an alibi. Tobacco oil on the stems points to Cass, who bought his 9:15 theater ticket at 5 PM. The torn patent drawings give the motive; Wren was at a cafe at 7:05.',array['00000000-0000-0000-0004-e00000000000','00000000-0000-0000-0004-e00000000001','00000000-0000-0000-0004-e00000000002','00000000-0000-0000-0004-e00000000003']::uuid[]);
insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0004-c00000000000','00000000-0000-0000-0004-a00000000000','00000000-0000-0000-0004-e00000000000','Cass smokes a pipe; the staged clock hands carry tobacco oil.');
insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0004-c00000000000','00000000-0000-0000-0004-a00000000000','00000000-0000-0000-0004-e00000000001','Cass says Roe died while he watched a play at 9:15, but death was near 7:30.');
insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0004-c00000000000','00000000-0000-0000-0004-a00000000001','00000000-0000-0000-0004-e00000000004','Wren was at a cafe at 7:05 PM, away from the shop at the time of death.');
insert into cases(id,number,title,difficulty,category,intro,location,est_minutes,motives,methods) values('00000000-0000-0000-0005-c00000000000',5,'The Ferry Manifest','hard','Homicide','Cargo inspector Joanna Pike was found dead beneath the open hold hatch of the night ferry Seren. It looks like a fall.','MV Seren, lower deck',45,array['Hiding a smuggling operation','Gambling debts','Revenge for a dismissal'],array['Accidental fall','Pushed, then staged as a fall','Poisoned tea']);
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0005-a00000000000','00000000-0000-0000-0005-c00000000000','Capt. Elias Brandt',60,'Ship captain','Thirty years at sea.','Deep in debt to a lender.','On the bridge all night.','"I never left the bridge."');
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0005-a00000000001','00000000-0000-0000-0005-c00000000000','Ines Calder',39,'Purser','Handles the cargo manifests.','Pike was auditing her paperwork.','Says she was asleep in her cabin.','"I turned in at midnight and heard nothing."');
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0005-a00000000002','00000000-0000-0000-0005-c00000000000','Rui Santos',26,'Deckhand','Newest crew member.','Fired by Pike last season.','On deck watch.','"I was at the stern rail till three."');
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0005-a00000000003','00000000-0000-0000-0005-c00000000000','Victor Hale',44,'Passenger','Travelling on a false name.','None known.','In the lounge.','"I was in the lounge with a book."');
insert into suspects(id,case_id,name,age,relation,background,motive_hint,alibi,statement) values('00000000-0000-0000-0005-a00000000004','00000000-0000-0000-0005-c00000000000','Dagny Voss',51,'Chief engineer','Runs the engine room.','None known.','Engine room checks.','"I logged every gauge reading."');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0005-e00000000000','00000000-0000-0000-0005-c00000000000','Two manifests','Purser''s office','Two versions of the cargo list differ on crate 14''s weight; the edited one is signed by Ines.','Reveals falsified cargo');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0005-e00000000001','00000000-0000-0000-0005-c00000000000','Hatch log','Bridge','The hold hatch was opened with the purser''s master key at 2:40 AM.','Puts Ines at the hold');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0005-e00000000002','00000000-0000-0000-0005-c00000000000','Pike''s notebook','Pike''s cabin','Last entry: ask Ines about crate 14 before docking.','Shows what Pike had found');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0005-e00000000003','00000000-0000-0000-0005-c00000000000','Ladder rung','Hold ladder','The rung she supposedly slipped on is clean, and her shoes carry no rust.','Shows the fall was staged');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0005-e00000000004','00000000-0000-0000-0005-c00000000000','Lender''s letter','Captain''s desk','A final notice for a personal loan, unrelated to cargo.','Red herring: explains the captain''s nerves');
insert into evidence(id,case_id,title,location,description,purpose) values('00000000-0000-0000-0005-e00000000005','00000000-0000-0000-0005-c00000000000','False passport','Victor''s bag','Victor is a journalist using a false name to cover ferry safety.','Red herring: explains the false name');
insert into case_solutions values('00000000-0000-0000-0005-c00000000000','00000000-0000-0000-0005-a00000000001',0,1,'Pike found that crate 14''s weight had been falsified, and her notebook shows she meant to confront Ines. Ines''s master key opened the hold at 2:40 AM, and the clean rung shows Pike did not slip. The captain''s debt and Victor''s alias are unrelated.',array['00000000-0000-0000-0005-e00000000000','00000000-0000-0000-0005-e00000000001','00000000-0000-0000-0005-e00000000002','00000000-0000-0000-0005-e00000000003']::uuid[]);
insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0005-c00000000000','00000000-0000-0000-0005-a00000000001','00000000-0000-0000-0005-e00000000001','Ines says she slept from midnight, but her master key opened the hatch at 2:40 AM.');
insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0005-c00000000000','00000000-0000-0000-0005-a00000000001','00000000-0000-0000-0005-e00000000000','Ines says she heard nothing, but she signed the edited manifest.');
insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0005-c00000000000','00000000-0000-0000-0005-a00000000000','00000000-0000-0000-0005-e00000000004','Brandt''s debt explains his nerves, not the death.');
insert into contradictions(case_id,suspect_id,evidence_id,finding) values('00000000-0000-0000-0005-c00000000000','00000000-0000-0000-0005-a00000000003','00000000-0000-0000-0005-e00000000005','Victor''s false name is for journalism; nothing places him near the hold.');
